    e11 = stwo_load_qm31(ext_params, 281u);
    e10 = stwo_qm31_mul(e3, e11);
    e11 = stwo_load_qm31(ext_params, 282u);
    e1 = stwo_qm31_mul(e0, e11);
    e11 = stwo_qm31_add(e10, e1);
    e1 = stwo_qm31_mul(e0, e3);
    e3 = stwo_load_qm31(ext_params, 283u);
    e0 = stwo_qm31_mul(e5, e3);
    e3 = stwo_load_qm31(ext_params, 284u);
    e10 = stwo_qm31_mul(e4, e3);
    e3 = stwo_qm31_add(e0, e10);
    e10 = stwo_qm31_mul(e4, e5);
    e5 = stwo_load_qm31(ext_params, 285u);
    e4 = stwo_qm31_mul(e7, e5);
    e5 = stwo_load_qm31(ext_params, 286u);
    e0 = stwo_qm31_mul(e6, e5);
    e5 = stwo_qm31_add(e4, e0);
    e0 = stwo_qm31_mul(e6, e7);
    e7 = StwoCudaQm31{ b130, b131, b131, b131 };
    e6 = stwo_qm31_mul(e9, e7);
    e7 = stwo_qm31_mul(e8, e2);
    e2 = stwo_qm31_add(e6, e7);
    e7 = stwo_qm31_mul(e8, e9);
    unsigned b292 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 16u, row_index, 0);
    unsigned b293 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 17u, row_index, 0);
    unsigned b294 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 18u, row_index, 0);
    unsigned b295 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 19u, row_index, 0);
    e9 = StwoCudaQm31{ b292, b293, b294, b295 };
    unsigned b296 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 20u, row_index, 0);
    unsigned b297 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 21u, row_index, 0);
    unsigned b298 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 22u, row_index, 0);
    unsigned b299 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 23u, row_index, 0);
    e8 = StwoCudaQm31{ b296, b297, b298, b299 };
    e6 = stwo_qm31_sub(e8, e9);
    e9 = stwo_qm31_mul(e6, e1);
    e6 = stwo_qm31_sub(e9, e11);
    // Canonical root accumulation begins at first readiness.
    StwoCudaQm31 acc = StwoCudaQm31{0u, 0u, 0u, 0u};
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e6, stwo_load_qm31(random_coeff_powers, rc_base + 0u)));
    unsigned b300 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 24u, row_index, 0);
    unsigned b301 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 25u, row_index, 0);
    unsigned b302 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 26u, row_index, 0);
    unsigned b303 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 27u, row_index, 0);
    e9 = StwoCudaQm31{ b300, b301, b302, b303 };
    e11 = stwo_qm31_sub(e9, e8);
    e8 = stwo_qm31_mul(e11, e10);
    e11 = stwo_qm31_sub(e8, e3);
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e11, stwo_load_qm31(random_coeff_powers, rc_base + 1u)));
    unsigned b304 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 28u, row_index, 0);
    unsigned b305 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 2u, 29u, row_index, 0);
